      const int off = (gc + kLanesPerRow * pass) * kChunk;
      // A zero source size zero-fills padding rows, so their scores are finite.
      cp_async16(dst + off, src + off, ok ? 16 : 0);
    }
    if (gc == 0) *vld_at(qraw, buf * kKeyBlock + gr) = ok ? 1 : 0;
  };

  if (nblocks > 0) gather(0, 0);
  cp_commit();

  float o[2 * kValueTiles][4];
#pragma unroll
  for (int f = 0; f < 2 * kValueTiles; ++f)
#pragma unroll
    for (int j = 0; j < 4; ++j) o[f][j] = 0.f;
  float m0 = kMaskBias;
  float m1 = kMaskBias;
  float l0 = 0.f;
  float l1 = 0.f;

  // P lane geometry, constant for the whole key loop.
  const int q_row = ((lane >> 3) & 1) * 8 + (lane & 7);
  const int q_hi = lane >> 4;
  const int r3 = lane & 7;
  const unsigned q_lane = smem_u32(qs + (static_cast<size_t>(16 * wm + q_row)) * kQStride);
  const unsigned p_lane = smem_u32(ps + (static_cast<size_t>(16 * wm + q_row)) * kPStride);
  const int kv_row0 = 8 * q_hi + (lane & 7);
  const int kv_lo16 = 16 * ((lane >> 3) & 1);
  const int prow = 16 * wm + row8;
  const int p_chunk = (2 * wn) "'^ (prow & 7);
  // Per-lane swizzle offsets for the four unrolled Q k-steps.
  int q_off[4];
#pragma unroll
  for (int u = 0; u < 4; ++u) q_off[u] = (q_hi + 2 * u) ''^ r3;

  for (int n = 0; n < nblocks; ++n) {
    const int buf = n & 1;
    __syncthreads();  // the buffer this prefetch targets is free again
    if (n + 1 < nblocks) gather(n + 1, buf ''^ 1);
    cp_commit();
    cp_wait();
    __syncthreads();  // gathered rows visible to every consumer

    // ---- QK: 16 heads x 16 keys, accumulated in fp32 ---------------------
    float s0[4] = {0.f, 0.f, 0.f, 0.f};
    float s1[4] = {0.f, 0.f, 0.f, 0.f};
    {
      const unsigned kv_lane =
          smem_u32(kvs + buf * (kKeyBlock * kKvStride) + static_cast<size_t>(16 * wn + kv_row0) * kKvStride) +
          kv_lo16;
#pragma unroll
      for (int g = 0; g < kKSteps / 4; ++g) {
#pragma unroll
        for (int u = 0; u < 4; ++u) {
          unsigned a[4];
          unsigned b[4];
          ldsm_x4(q_lane + 128 * g + 16 * q_off[u], a);
          ldsm_x4_t(kv_lane + 128 * g + 32 * u, b);
          mma_bf16(s0, a, b[0], b[1]);
          mma_bf16(s1, a, b[2], b[3]);
        }
      }
    }

    // ---- mask, scale, cross-warp row max ---------------------------------
    float p0[4];
    float p1[4];
    float rs0;
    float rs1;
    {
#pragma unroll
      for (int j = 0; j < 4; ++j) {
        s0[j] *= kScale;
        s1[j] *= kScale;
      }
      const unsigned char* vp = vld_at(qraw, buf * kKeyBlock) + wn * kKeysPerWarp + 2 * col4;
      const float f0 = vp[0] ? 0.f : kMaskBias;
      const float f1 = vp[1] ? 0.f : kMaskBias;
      const float f2 = vp[8] ? 0.f : kMaskBias;
      const float f3 = vp[9] ? 0.f : kMaskBias;

      float rm0 = fmaxf(fmaxf(s0[0] + f0, s0[1] + f1), fmaxf(s1[0] + f2, s1[1] + f3));
      float rm1 = fmaxf(fmaxf(s0[2] + f0, s0[3] + f1), fmaxf(s1[2] + f2, s1[3] + f3));
      rm0 = fmaxf(rm0, __shfl_xor_sync(0xffffffffu, rm0, 1));
      rm0 = fmaxf(rm0, __shfl_xor_sync(0xffffffffu, rm0, 2));
      rm1 = fmaxf(rm1, __shfl_xor_sync(0xffffffffu, rm1, 1));
      rm1 = fmaxf(rm1, __shfl_xor_sync(0xffffffffu, rm1, 2));
      if (col4 == 0) {
        *pad_f(kvraw, ((wm * kWarpsN + wn) << 4) + row8) = rm0;
        *pad_f(kvraw, ((wm * kWarpsN + wn) << 4) + row8 + 8) = rm1;
      }
      group_bar(wm + 1);

      float a0 = *pad_f(kvraw, (wm * kWarpsN << 4) + row8);
      float a1 = *pad_f(kvraw, (wm * kWarpsN << 4) + row8 + 8);
#pragma unroll
      for (int w = 1; w < kWarpsN; ++w) {
        a0 = fmaxf(a0, *pad_f(kvraw, ((wm * kWarpsN + w) << 4) + row8));
        a1 = fmaxf(a1, *pad_f(kvraw, ((wm * kWarpsN + w) << 4) + row8 + 8));
      }
      const float nm0 = fmaxf(m0, a0);
      const float nm1 = fmaxf(m1, a1);
      const float r0 = (nm0 == m0) ? 1.f : exp2f((m0 - nm0) * kLog2e);
      const float r1 = (nm1 == m1) ? 1.f : exp2f((m1 - nm1) * kLog2e);
      m0 = nm0;
      m1 = nm1;
      if (r0 != 1.f || r1 != 1.f) {
#pragma unroll
        for (int f = 0; f < 2 * kValueTiles; ++f) {
          o[f][0] *= r0;
          o[f][1] *= r0;
          o[f][2] *= r1;
          o[f][3] *= r1;
        }
      }
      l0 *= r0;
      l1 *= r1;

      // p = exp2((score + mask - m) * log2e); masked keys collapse to zero.
      const float t0 = m0 * kLog2e;
      const float t1 = m1 * kLog2e;
      p0[0] = exp2f(fmaf(s0[0] + f0, kLog2e, -t0));
      p0[1] = exp2f(fmaf(s0[1] + f1, kLog2e, -t0));
      p0[2] = exp2f(fmaf(s0[2] + f0, kLog2e, -t1));
      p0[3] = exp2f(fmaf(s0[3] + f1, kLog2e, -t1));
      p1[0] = exp2f(fmaf(s1[0] + f2, kLog2e, -t0));
      p1[1] = exp2f(fmaf(s1[1] + f3, kLog2e, -t0));
      p1[2] = exp2f(fmaf(s1[2] + f2, kLog2e, -t1));
      p1[3] = exp2f(fmaf(s1[3] + f3, kLog2e, -t1));

      rs0 = (p0[0] + p0[1]) + (p1[0] + p1[1]);
      rs1 = (p0[2] + p0[3]) + (p1[2] + p1[3]);
      rs0 += __shfl_xor_sync(0xffffffffu, rs0, 1);
      rs0 += __shfl_xor_sync(0xffffffffu, rs0, 2);
      rs1 += __shfl_xor_sync(0xffffffffu, rs1, 1);
      rs1 += __shfl_xor_sync(0xffffffffu, rs1, 2);
      l0 += rs0;
      l1 += rs1;
    }

    // ---- publish P to shared memory --------------------------------------
    {
      const int p_lo = (2 * wn + 1) ''^ (prow & 7);
      *reinterpret_cast<unsigned*>(reinterpret_cast<unsigned char*>(ps) + prow * 2 * kPStride + 16 * p_chunk + 4 * col4) =
          pack2(p0[0], p0[1]);
      *reinterpret_cast<unsigned*>(reinterpret_cast<unsigned char*>(ps) + (prow + 8) * 2 * kPStride + 16 * p_chunk + 4 * col4) =
          pack2(p0[2], p0[3]);
      *reinterpret_cast<unsigned*>(reinterpret_cast<unsigned char*>(ps) + prow * 2 * kPStride + 16 * p_lo + 4 * col4) =
          pack2(p1[0], p1[1]);
      *reinterpret_cast<unsigned*>(reinterpret_cast<unsigned char*>(ps) + (prow + 8) * 2 * kPStride + 16 * p_lo + 4 * col4) =
          pack2(p1[2], p1[3]);
    }
    group_bar(wm + 1);

    // ---- PV: 16 heads x 128 values ---------------------------------------
    {
      const unsigned v_lane =
          smem_u32(kvs + buf * (kKeyBlock * kKvStride) + static_cast<size_t>(kv_row0) * kKvStride) +
          kv_lo16 + 2 * (kValuesPerWarp * wn);
#pragma unroll
      for (int kk = 0; kk < 4; ++kk) {
        unsigned pa[4];
        ldsm_x4(p_lane + 16 * (((2 * kk + q_hi) ''^ r3) & 7), pa);
#pragma unroll
        for (int j = 0; j < kValueTiles; ++j) {
          unsigned vb[4];
          ldsm_x4_t(v_lane + kk * (16 * kKvStride * 2) + 32 * j, vb);
          mma_bf16(o[2 * j], pa, vb[0], vb[1]);
          mma_bf16(o[2 * j + 1], pa, vb[2], vb[3]);
        }
      }
    }
  }

  // ---- combine the four value-group partial sums, then write the outputs --
  if (col4 == 0) {
    *pad_f(kvraw, ((wm * kWarpsN + wn) << 4) + row8) = l0;
    *pad_f(kvraw, ((wm * kWarpsN + wn) << 4) + row8 + 8) = l1;
  }
  group_bar(wm + 1);
  float L0 = 0.f;
  float L1 = 0.f;
#pragma unroll
  for (int w = 0; w < kWarpsN; ++w) {
    L0 += *pad_f(kvraw, ((wm * kWarpsN + w) << 4) + row8);
    L1 += *pad_f(kvraw, ((wm * kWarpsN + w) << 4) + row8 + 8);
  }
  const float inv0 = L0 > 0.f ? 1.f / L0 : 0.f;
  const float inv1 = L1 > 0.f ? 1.f / L1 : 0.f;

  const size_t orow = static_cast<size_t>(token) * kHeads + head0 + wm * kHeadsPerWarp + row8;
  const int vcol = kValuesPerWarp * wn + 2 * col4;
#pragma unroll
  for (int f = 0; f < 2 * kValueTiles; ++f) {
    bf16* dst = out + (orow * kValueDim) + vcol + 8 * f;
    *reinterpret_cast<unsigned*>(dst) = pack2(o[f][0] * inv0, o[f][1] * inv0);
    *reinterpret_cast<unsigned*>(dst + 8 * kValueDim) = pack2(o[f][2] * inv1, o[f][3] * inv1);
  }
  if (col4 == 0) {
    max_logits[orow] = m0;
    row_lse[orow] = m0 + logf(L0);
    max_logits[orow + 8] = m1;
    row_lse[orow + 8] = m1 + logf(L1);
  }
}

// ------------------------------------------------------------ host wrapper --
void kernel(const torch::Tensor& q, const torch::Tensor& kv, const torch::Tensor& indices,
            const torch::Tensor& out, const torch::Tensor& max_logits, const torch::Tensor& lse) {
  TORCH_CHECK(q.is_cuda() && kv.is_cuda() && indices.is_cuda() && out.is_cuda(), "CUDA tensors required");
  TORCH_CHECK(q.scalar_type() == torch::kBFloat16 && kv.scalar_type() == torch::kBFloat16 &&
                  out.scalar_type() == torch::kBFloat16,
              "bf16 q/kv/output required");
  TORCH_CHECK(indices.scalar_type() == torch::kInt32, "int32 indices required");
  TORCH_CHECK(max_logits.scalar_type() == torch::kFloat32 && lse.scalar_type() == torch::kFloat32,
              "fp32 statistics required");
  TORCH_CHECK(q.is_contiguous() && kv.is_contiguous() && indices.is_contiguous() && out.is_contiguous() &&
                  max_logits.is_contiguous() && lse.is_contiguous(),
              "contiguous tensors required");
  TORCH_CHECK(q.dim() == 3 && q.size(0) == kTokens && q.size(1) == kHeads && q.size(2) == kQkDim, "bad q");
  TORCH_CHECK(kv.dim() == 3 && kv.size(0) == kTokens && kv.size(1) == 1 && kv.size(2) == kQkDim, "bad kv");
  TORCH_CHECK(indices.dim() == 3 && indices.size(0) == kTokens && indices.size(1) == 1 && indices.size(2) == kTopK,
              "bad indices");
  TORCH_CHECK(out.dim() == 3 && out.size(0) == kTokens && out.size(1) == kHeads && out.size(2) == kValueDim, "bad out");
  TORCH_CHECK(max_logits.numel() == static_cast<int64_t>(kTokens) * kHeads, "bad max_logits");
  TORCH_CHECK(lse.numel() == static_cast<int64_t>(kTokens) * kHeads, "bad lse");

  c10::cuda::CUDAGuard guard(q.device());
  static const bool configured = [] {
    cudaFuncSetAttribute(sparse_mla_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemBytes);
    return true;
  }();
  (void)configured;

  const auto stream = c10::cuda::getCurrentCUDAStream(q.get_device()).stream();
  const dim3 grid(kTokens, kHeads / kHeadsPerCta);
  sparse_mla_kernel<<<grid, kThreads, kSmemBytes, stream>>>(
      reinterpret_cast<const bf16*>(q.data_ptr<at::BFloat16>()),
      reinterpret_cast<const bf16*>(kv.data_ptr<at::BFloat16>()), indices.data_ptr<int>(),
      reinterpret_cast<bf16*>(out.data_ptr<at::BFloat16>()), max_logits.data_ptr<float>(),
      lse.data_ptr<float>());
  const cudaError_t error = cudaGetLastError();
  TORCH_CHECK(error == cudaSuccess, cudaGetErrorString(error));
}

}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) { module.def("kernel", &kernel); }
